"""Fixed-shape CPU team pools generated by the pinned Showdown reference.

Typed Hidden Power moves fall back to the plain move row when necessary;
Gen 5 type and power remain encoded in the member's IVs.
"""

import argparse
import json
from collections import Counter
from dataclasses import dataclass, fields
from pathlib import Path

import numpy as np
from numpy.typing import NDArray

from pokejax.tables import NONE_ROW, STAT_NAMES, Tables, load_tables

TEAM_SLOTS = 6
MOVE_SLOTS = 4
GENDERLESS = 0
MALE = 1
FEMALE = 2
GENDER_INDEX = {"N": GENDERLESS, "": GENDERLESS, "M": MALE, "F": FEMALE}
FORMAT = "gen5randombattle"
HIDDEN_POWER_TYPES = (
	"fighting",
	"flying",
	"poison",
	"ground",
	"rock",
	"bug",
	"ghost",
	"steel",
	"fire",
	"water",
	"grass",
	"electric",
	"psychic",
	"ice",
	"dragon",
	"dark",
)
HIDDEN_POWER_WEIGHTS = (1, 2, 4, 16, 32, 8)


@dataclass(frozen=True)
class TeamPool:
	species: NDArray[np.int16]
	level: NDArray[np.uint8]
	moves: NDArray[np.int16]
	ability: NDArray[np.int16]
	item: NDArray[np.int16]
	nature: NDArray[np.int8]
	gender: NDArray[np.int8]
	evs: NDArray[np.uint8]
	ivs: NDArray[np.uint8]
	happiness: NDArray[np.uint8]
	team_size: NDArray[np.uint8]
	seed: int
	showdown_commit: str


def _integer(value, minimum, maximum, name):
	if type(value) is not int or not minimum <= value <= maximum:
		raise ValueError(f"{name} must be an integer in {minimum}..{maximum}: {value!r}")
	return value


def _move_id(move, member, tables):
	if move in tables.moves.index:
		return move
	if (
		move.startswith("hiddenpower")
		and move[11:] in HIDDEN_POWER_TYPES
		and "hiddenpower" in tables.moves.index
	):
		# Only collapse a typed id when the IVs actually preserve that type.
		ivs = [member["ivs"][stat] for stat in STAT_NAMES]
		bits = sum((iv & 1) * weight for iv, weight in zip(ivs, HIDDEN_POWER_WEIGHTS))
		if HIDDEN_POWER_TYPES[bits * 15 // 63] != move[11:]:
			raise ValueError(f"{move} does not match the member's Hidden Power IVs")
		return "hiddenpower"
	return move


def load_team_pool(path, tables: Tables) -> TeamPool:
	"""Read a JSON pool and resolve its recorded sets."""
	with Path(path).open(encoding="utf-8") as source:
		return team_pool_from_data(json.load(source), tables)


def team_pool_from_data(data, tables: Tables) -> TeamPool:
	"""Resolve all ids, reporting every unknown id and its occurrence count.

	Inputs must contain exactly six members per team and one to four moves
	per member. Numeric ranges are checked before casting to compact dtypes.
	"""
	if data["format"] != FORMAT:
		raise ValueError(f"Expected format {FORMAT}, got {data['format']!r}")
	teams = data["teams"]
	count = len(teams)
	if data["count"] != count:
		raise ValueError("Team count does not match metadata")
	shape = (count, TEAM_SLOTS)
	columns = {
		"species": np.zeros(shape, dtype=np.int16),
		"level": np.zeros(shape, dtype=np.uint8),
		"moves": np.zeros((*shape, MOVE_SLOTS), dtype=np.int16),
		"ability": np.zeros(shape, dtype=np.int16),
		"item": np.zeros(shape, dtype=np.int16),
		"nature": np.zeros(shape, dtype=np.int8),
		"gender": np.zeros(shape, dtype=np.int8),
		"evs": np.zeros((*shape, len(STAT_NAMES)), dtype=np.uint8),
		"ivs": np.zeros((*shape, len(STAT_NAMES)), dtype=np.uint8),
		"happiness": np.zeros(shape, dtype=np.uint8),
		"team_size": np.zeros(count, dtype=np.uint8),
	}
	unresolved = Counter()

	def resolve(kind, id_):
		table = getattr(tables, kind)
		if kind == "species":
			id_ = table.cosmetic_aliases.get(id_, id_)
		if id_ not in table.index:
			unresolved[kind, id_] += 1
			return NONE_ROW
		return table.index[id_]

	for t, team in enumerate(teams):
		if len(team) != TEAM_SLOTS:
			raise ValueError(f"Team {t} has {len(team)} members; expected {TEAM_SLOTS}")
		columns["team_size"][t] = len(team)
		for slot, member in enumerate(team):
			for column, kind in (
				("species", "species"),
				("ability", "abilities"),
				("item", "items"),
				("nature", "natures"),
			):
				id_ = member[column]
				if column in ("species", "ability") and not id_:
					raise ValueError(f"Team {t} member {slot}: {column} cannot be empty")
				columns[column][t, slot] = resolve(kind, id_)
			for column, minimum, maximum in (("level", 1, 100), ("happiness", 0, 255)):
				columns[column][t, slot] = _integer(member[column], minimum, maximum, column)
			if member["gender"] not in GENDER_INDEX:
				raise ValueError(f"Unknown gender: {member['gender']!r}")
			columns["gender"][t, slot] = GENDER_INDEX[member["gender"]]
			for column, maximum in (("evs", 255), ("ivs", 31)):
				columns[column][t, slot] = [
					_integer(member[column][stat], 0, maximum, f"{column}.{stat}")
					for stat in STAT_NAMES
				]
			moves = member["moves"]
			if not 1 <= len(moves) <= MOVE_SLOTS or any(not move for move in moves):
				raise ValueError(f"Team {t} member {slot} must have 1..{MOVE_SLOTS} nonempty moves")
			for m, move in enumerate(moves):
				columns["moves"][t, slot, m] = resolve("moves", _move_id(move, member, tables))
	if unresolved:
		details = "; ".join(
			f"{kind}.{id_}: {occurrences}"
			for (kind, id_), occurrences in sorted(unresolved.items())
		)
		raise ValueError(f"Unresolved Showdown ids (occurrence counts): {details}")
	return TeamPool(**columns, seed=data["seed"], showdown_commit=data["showdownCommit"])


def save_npz(pool: TeamPool, path):
	"""Save arrays and scalar metadata without object arrays or pickle."""
	with Path(path).open("wb") as target:
		np.savez_compressed(
			target, **{field.name: getattr(pool, field.name) for field in fields(pool)}
		)


def load_npz(path) -> TeamPool:
	"""Load a pool saved by save_npz; arrays remain NumPy arrays on the CPU."""
	with np.load(path, allow_pickle=False) as source:
		columns = {field.name: source[field.name] for field in fields(TeamPool)}
	columns["seed"] = int(columns["seed"].item())
	columns["showdown_commit"] = str(columns["showdown_commit"].item())
	return TeamPool(**columns)


def main():
	parser = argparse.ArgumentParser(description=__doc__)
	parser.add_argument("json_path", type=Path)
	parser.add_argument("npz_path", type=Path)
	args = parser.parse_args()
	pool = load_team_pool(args.json_path, load_tables())
	args.npz_path.parent.mkdir(parents=True, exist_ok=True)
	save_npz(pool, args.npz_path)
	counts = {
		name: np.count_nonzero(np.unique(getattr(pool, name)))
		for name in ("species", "moves", "ability", "item")
	}
	print(
		f"{len(pool.team_size)} teams; distinct: {counts['species']} species, "
		f"{counts['moves']} moves, {counts['ability']} abilities, {counts['item']} items"
	)


if __name__ == "__main__":
	main()
